import '../models/video.dart'; import '../services/api_client.dart';
class VideoRepository { VideoRepository(this._api); final ApiClient _api; Future<List<Video>> featured() async { final r = await _api.dio.get('/videos/featured'); return (r.data['items'] as List).map((e) => Video.fromJson(e)).toList(); } Future<Video> details(String id) async => Video.fromJson((await _api.dio.get('/videos/$id')).data); Future<void> saveProgress(String id, Duration p, Duration total) => _api.dio.post('/history', data: {'videoId': id, 'currentPosition': p.inSeconds, 'watchedPercentage': total.inSeconds == 0 ? 0 : p.inSeconds * 100 / total.inSeconds}); }
